function bearer() {
    return {
        headers: {
            Authorization: `Bearer ${token.access_token}`,
        },
    };
}

async function axiosCall(url, response, specialRes = false) {
    let config;
    if (auth) config = bearer();
    else {
        if (!initAuth) console.log('Error: Please use " corporate.auth(user, pwd) " for authentication"');
        await new Promise((resolve) => authEvent.on('resolve', resolve));
        config = bearer();
    }

    try {
        const res = await axios.get(url, config);
        const data = {};

        // CASE 1: When api response = csv & response = csv
        if (response === 'csv') {
            return res.data;
        }

        if (response === 'file') {
            return res.data;
        }

        // CASE 2: When api response = json & response = json
        // Handle JSON Data when response = $response in url
        if (specialRes === true) {
            // Handle error messages in json response
            if (response === "json" && res.data.status &&
                (res.data.status.startsWith('No data exists') || res.data.status.startsWith('Invalid Date range') ||
                    res.data.status.startsWith('365 days period is allowed in annoucements for company.') ||
                    res.data.status.startsWith('Max 30 days period is allowed in annoucements for company.') ||
                    res.data.status.startsWith('One day period is only allowed in annoucements.') ||
                    res.data.status.startsWith('There is no row at position 0.') ||
                    res.data.status.startsWith('Croporate Segment not subscribed') ||
                    res.data.status.startsWith('2 days period is allowed') ||
                    res.data.status.startsWith('Invalid date format. Pl supply date in yyMMdd HH:mm:ss format'))) {
                console.log("json error: ", res.data);
                return res.data;
            }

            const records = Array.isArray(res.data)
                ? res.data
                : res.data.Records ?? res.data;

            if (!records || records.length === 0) {
                data.status = "No data exists";
                data.Records = "";
            } else {
                data.status = "Success";
                data.Records = records;
            }

            // getAnnouncementsForCompniesFrom
            res.data.count !== undefined ? data.count = res.data.count && res.data.count : '';

            // getAllResultItemsById
            res.data.Details !== undefined ? data.Details = res.data.Details && res.data.Details : '';

            return data;
        }

        // CASE 3: When api response = csv & response = json, convert csv -> json
        // Handle Json Data when response = csv directly in url
        const parsed = Papa.parse(res.data, {
            header: true,
            skipEmptyLines: true
        });

        // Handle error messages in json response
        if (response === "json" &&
            (res.data.startsWith('No data exists') || res.data.startsWith('Invalid Date range') ||
                res.data.startsWith('365 days period is allowed in annoucements for company.') ||
                res.data.startsWith('Max 30 days period is allowed in annoucements for company.') ||
                res.data.startsWith('One day period is only allowed in annoucements.') ||
                res.data.startsWith('There is no row at position 0.') ||
                res.data.startsWith('Croporate Segment not subscribed') ||
                res.data.startsWith('2 days period is allowed') ||
                res.data.startsWith('Invalid date format. Pl supply date in yyMMdd HH:mm:ss format'))) {

            data.status = res.data;
            data.Records = '';
            return data;
        }

        const records = parsed.data.map(row => {
            const obj = {};
            for (const k in row) {
                const v = row[k];
                obj[k] = v === "" ? null : !isNaN(v) ? Number(v) : v;
            }
            return obj;
        });

        if (!records || records.length === 0) {
            data.status = "No data exists";
            data.Records = "";
        } else {
            data.status = "Success";
            data.Records = records;
        }

        return data;
    } catch (err) {
        const data = {};
        data.status = 'Something went wrong. Please check internet connection';

        // Token expired but refreshable
        if (
            err.response &&
            err.response.data &&
            err.response.data.Message &&
            err.response.data.Message.startsWith('Authorization has been denied for this request') &&
            Date.now() < token.time
        ) {
            if (!authProcessing) {
                await reAuth();
            } else {
                await utils.wait(2000);
            }
            return axiosCall(url);
        }

        // Rate limit handling
        if (err.response && err.response.data === 'API request quota exceeded!') {
            // if (data.status.startsWith('QVBJIGN')) data.status = 'Error : Rate limit exceeded';
            console.log('Rate limit reached - Requests are being staggered')
            await utils.wait(1000);
            return axiosCall(url);
        }

        // Other API errors
        if (err.response && err.response.data) data.status = err.response.data;

        throw data;
    }
}

const reAuth = async () => {
    authProcessing = true;
    await this.auth(user, pwd, true);
    setTimeout(() => {
        authProcessing = false;
    }, 1000);
};

function formatDateTime(arg, argDate) {
    let d;

    // Case 1: TrueData format "251201T09:00:00"
    if (typeof argDate === "string" && argDate.includes("T")) {
        const yy = argDate.slice(0, 2);
        const mm = argDate.slice(2, 4);
        const dd = argDate.slice(4, 6);
        d = new Date(`20${yy}-${mm}-${dd}`);
    }
    // Case 2: ISO date / Date object / undefined
    else {
        d = new Date(argDate || new Date());
    }

    if (isNaN(d.getTime())) d = new Date();
    const yy = String(d.getFullYear()).slice(2);
    const mm = String(d.getMonth() + 1).padStart(2, "0");
    const dd = String(d.getDate()).padStart(2, "0");
    const time = arg === "to" ? "23:59:59" : "00:00:00";

    return `${yy}${mm}${dd} ${time}`;
}

function formatDate(argDate) {
    if (!argDate) {
        const d = new Date();
        return `${String(d.getFullYear()).slice(2)}${utils.zeroChecker(d.getMonth() + 1)}${utils.zeroChecker(d.getDate())}`;
    }

    // Case 1: TrueData format → "251201T09:00:00"
    if (typeof argDate === "string" && argDate.includes("T") && argDate.length >= 6) {
        return argDate.substring(0, 6);
    }

    // Case 2: ISO date / Date object → "2026-12-31" or new Date()
    const d = new Date(argDate);
    if (isNaN(d.getTime())) return "";

    return `${String(d.getFullYear()).slice(2)}${utils.zeroChecker(d.getMonth() + 1)}${utils.zeroChecker(d.getDate())}`;
}

function filterArray(arr) {
    if (!Array.isArray(arr)) return "";
    return arr.join(",");
}